import{_ as B,H as e,f as t,i as a}from"./chunks/framework.BH2BK_3i.js";const o=JSON.parse('{"title":"第二十七封信-什么相机是最好的相机？（引子）","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第二十七封信-什么相机是最好的相机？（引子）.md","filePath":"去无方向的信/第二十七封信-什么相机是最好的相机？（引子）.md","lastUpdated":1795542896000}'),p={name:"去无方向的信/第二十七封信-什么相机是最好的相机？（引子）.md"};function A(i,E,s,n,C,_){return e(),t("div",null,[...E[0]||(E[0]=[a('<h1 id="第二十七封信-什么相机是最好的相机-引子" tabindex="-1">第二十七封信-什么相机是最好的相机？（引子） <a class="header-anchor" href="#第二十七封信-什么相机是最好的相机-引子" aria-label="Permalink to &quot;第二十七封信-什么相机是最好的相机？（引子）&quot;">​</a></h1><p>生生：</p><p>你好哇。</p><p>这次我们来聊聊相机。</p><p>感觉相机这个事儿应该是在最开始聊的，对吧，没相机就聊拍摄技术很奇怪，但为什么现在才聊呢？因为如果没有前面咱们讲过的那些东西，相机这个东西是没法儿聊的……如果聊相机变成了聊品牌、聊像素、聊连拍速度、聊眼控对焦啥的，那就等于什么都没有聊。</p><p>聊相机的话，咱们会直接从最根本的一个概念入手：画幅。</p><p>“全画幅”这个说法我相信你肯定经常会听到，因为我们现在已经进入一个全民全画幅的时代了，感觉不是全画幅的相机都已经很少会有人用了……那到底什么是全画幅？</p><p>咱们退回到胶片时代。</p><p>那时候有一种胶片叫 135 胶片，也叫 35mm 胶片（这个 35mm 跟镜头的那个 35mm 焦段无关），135 的胶卷我相信你应该见过，因为这种大小的胶片非常常见，就是以前家里傻瓜相机用的那种，柯达呀，富士呀，长长的卷成一个卷，抻直了看，每八个小孔就是一张照片儿，一卷一共 36 张。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2583%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E5%25BC%2595%25E5%25AD%2590%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2583%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E5%25BC%2595%25E5%25AD%2590%25EF%25BC%2589/1.png" alt=""></a></p><p>而如今我们常用的相机已经不用胶片这种东西了，取而代之的是一种叫感光元件（CCD、CMOS 什么的）的东西，跟当年的胶片是同一个意思，无非是，胶片是用化学方式感光，我们现在用电子手段感光。</p><p>但这都不重要，我把 35mm 胶片搬出来的意思只有一个：在数码相机时代，我们管感光元件大小跟 35mm 胶片大小一样的相机叫全画幅相机。</p><p>除了全画幅相机，市面上还有各种非全画幅相机：</p><p>先说感光元件比全画幅小的，比如 APS-C（最常见的）、APS-H（已经不常见了）、M43 啥的，比 M43 更小的就是 1 英寸，1 英寸基本上就是十几年我们常用的那种卡片机的感光元件的大小……比 1 英寸再小的，就是我们现在手机上用的这些感光元件了，但是，据说现在已经有感光元件面积达到 1 英寸的手机相机了。</p><p>说完了小了，咱们说大的，比全画幅大的画幅还有没有呢？当然有，比如各种尺寸的中画幅和各种尺寸的大画幅。</p><p>强调一句，一定不要看见“中”和“全”就觉得中画幅比全画幅小，因为中画幅非但不小，反而比全画幅的“底”大好多。是的，我们也管画幅叫“底”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2583%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E5%25BC%2595%25E5%25AD%2590%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2583%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E5%25BC%2595%25E5%25AD%2590%25EF%25BC%2589/2.png" alt=""></a></p><ul><li>还有很多比全画幅小的画幅还有很多比 5x8 大画幅大的画幅</li></ul><p>那么现在问题来了，分了这么多种大大小小的画幅，麻麻烦烦的，他们到底有什么区别？摄影界常说的“底大一级压死人”又是什么意思？听起来好像是底越大越好，那我们为什么不都用大画幅相机或中画幅相机拍照片儿呢？如果先不考虑大画幅和中画幅的话，买相机一定要买全画幅相机么？好多人都觉得拿着一台非全画幅相机（也叫残幅相机）特别丢人，显得特别不专业，但残幅相机就真的那么残么？卡片机（1 英寸底）到底还有没有活下去的必要和机会？手机上的那个相机，对我们来说，到底意味着什么？</p><p>今天只是开个头，咱们之后有时间再细聊。</p>',20)])])}const m=B(p,[["render",A]]);export{o as __pageData,m as default};
